package com.bank.loadbalancer.instance;

import java.util.concurrent.atomic.AtomicInteger;

public class ServiceInstance {
    private final String id;
    private final int weight;                  // capacity weight (bigger = more share)
    private volatile boolean healthy = true;
    private final AtomicInteger activeConnections = new AtomicInteger(0);

    public ServiceInstance(String id, int weight) { this.id = id; this.weight = weight; }

    public String getId() { return id; }
    public int getWeight() { return weight; }
    public boolean isHealthy() { return healthy; }
    public void setHealthy(boolean healthy) { this.healthy = healthy; }
    public int getActiveConnections() { return activeConnections.get(); }
    public void acquire() { activeConnections.incrementAndGet(); }
    public void release() { activeConnections.decrementAndGet(); }
}
