package com.bank.loadbalancer.algorithm;

import com.bank.loadbalancer.instance.ServiceInstance;
import java.util.Comparator;
import java.util.List;

// Least-connections: send to the instance with the fewest active requests.
public class LeastConnectionsBalancer implements LoadBalancer {
    @Override public ServiceInstance choose(List<ServiceInstance> healthy) {
        return healthy.stream()
                .min(Comparator.comparingInt(ServiceInstance::getActiveConnections))
                .orElseThrow();
    }
    @Override public String name() { return "least-connections"; }
}
