package com.bank.loadbalancer.algorithm;

import com.bank.loadbalancer.instance.ServiceInstance;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

// Weighted round-robin: bigger-weight instances get proportionally more requests.
public class WeightedRoundRobinBalancer implements LoadBalancer {
    private final AtomicInteger counter = new AtomicInteger(0);

    @Override public ServiceInstance choose(List<ServiceInstance> healthy) {
        int totalWeight = healthy.stream().mapToInt(ServiceInstance::getWeight).sum();
        int pick = Math.abs(counter.getAndIncrement() % totalWeight);
        int running = 0;
        for (ServiceInstance inst : healthy) {
            running += inst.getWeight();
            if (pick < running) return inst;
        }
        return healthy.get(healthy.size() - 1);
    }
    @Override public String name() { return "weighted-round-robin"; }
}
