package com.bank.loadbalancer.health;

import com.bank.loadbalancer.instance.ServiceInstance;
import java.util.List;
import java.util.stream.Collectors;

// Only healthy instances are eligible for load balancing.
public class HealthChecker {
    public List<ServiceInstance> healthyOnly(List<ServiceInstance> all) {
        return all.stream().filter(ServiceInstance::isHealthy).collect(Collectors.toList());
    }
}
