package com.bank.loadbalancer;

import com.bank.loadbalancer.algorithm.*;
import com.bank.loadbalancer.health.HealthChecker;
import com.bank.loadbalancer.instance.ServiceInstance;
import java.util.*;
import java.util.logging.*;

public class LoadBalancerDemo {
    public static void main(String[] args) {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());
        Logger log = Logger.getLogger(LoadBalancerDemo.class.getName());

        HealthChecker health = new HealthChecker();
        List<ServiceInstance> instances = new ArrayList<>(List.of(
                new ServiceInstance("txn-1", 1),
                new ServiceInstance("txn-2", 1),
                new ServiceInstance("txn-3", 1)));

        // ROUND-ROBIN: even rotation when requests are uniform.
        log.info("=== Round-robin (uniform) ===");
        LoadBalancer rr = new RoundRobinBalancer();
        Map<String,Integer> rrCount = new TreeMap<>();
        for (int i = 0; i < 9; i++) {
            ServiceInstance chosen = rr.choose(health.healthyOnly(instances));
            rrCount.merge(chosen.getId(), 1, Integer::sum);
        }
        log.info("round-robin distribution: " + rrCount);

        // LEAST-CONNECTIONS: txn-1 is stuck on 5 slow requests; new work avoids it.
        log.info("=== Least-connections (uneven load) ===");
        instances.get(0).acquire(); instances.get(0).acquire(); instances.get(0).acquire();
        instances.get(0).acquire(); instances.get(0).acquire(); // txn-1 busy
        LoadBalancer lc = new LeastConnectionsBalancer();
        Map<String,Integer> lcCount = new TreeMap<>();
        for (int i = 0; i < 6; i++) {
            ServiceInstance chosen = lc.choose(health.healthyOnly(instances));
            chosen.acquire();
            lcCount.merge(chosen.getId(), 1, Integer::sum);
        }
        log.info("least-connections distribution: " + lcCount + " (txn-1 avoided while busy)");

        // WEIGHTED: txn-3 is on a 2x machine, gets 2x share.
        log.info("=== Weighted round-robin (mixed fleet) ===");
        List<ServiceInstance> weighted = List.of(
                new ServiceInstance("txn-1", 1),
                new ServiceInstance("txn-2", 1),
                new ServiceInstance("txn-3", 2)); // double capacity
        LoadBalancer wrr = new WeightedRoundRobinBalancer();
        Map<String,Integer> wCount = new TreeMap<>();
        for (int i = 0; i < 8; i++) {
            ServiceInstance chosen = wrr.choose(health.healthyOnly(weighted));
            wCount.merge(chosen.getId(), 1, Integer::sum);
        }
        log.info("weighted distribution: " + wCount + " (txn-3 gets ~2x)");

        // HEALTH CHECK: txn-2 dies and is excluded from rotation.
        log.severe("txn-2 failed health check");
        instances.get(1).setHealthy(false);
        LoadBalancer rr2 = new RoundRobinBalancer();
        Set<String> served = new TreeSet<>();
        for (int i = 0; i < 6; i++) served.add(rr2.choose(health.healthyOnly(instances)).getId());
        log.info("after health check, requests served only by: " + served + " (no txn-2)");
    }
}

